        a = point(i)
        b = point(j)
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return (dx * dx + dy * dy) ** 0.5

    customers = list(range(1, n + 1))
    if not customers:
        return []

    # Order customers by a deterministic geometric key if available.
    if coords is not None:
        depot = point(0)
        ordered = sorted(customers, key=lambda c: (
            (point(c)[1] - depot[1]) / (abs(point(c)[0] - depot[0]) + abs(point(c)[1] - depot[1]) + 1e-12),
            dist(0, c),
            c
        ))
    else:
        ordered = customers[:]

    # Initial feasible construction: best insertion into current/open routes.
    routes = []
    route_loads = []

    for c in ordered:
        d = demands[c]
        best = None
        best_cost = None

        for r_idx, r in enumerate(routes):
            if route_loads[r_idx] + d > capacity:
                continue
            if not r:
                cost = 2.0 * dist(0, c)
                pos = 0
            else:
                best_delta = None
                best_pos = 0
                prev = 0
                for i in range(len(r) + 1):
                    nxt = 0 if i == len(r) else r[i]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_pos = i
                    prev = nxt
                cost = best_delta
                pos = best_pos
            if best_cost is None or cost < best_cost - 1e-12 or (abs(cost - best_cost) <= 1e-12 and r_idx < best[0]):
                best_cost = cost
                best = (r_idx, pos)

        if best is None:
            routes.append([c])
            route_loads.append(d)
        else:
            r_idx, pos = best
            routes[r_idx].insert(pos, c)
            route_loads[r_idx] += d

    def route_load(r):
        s = 0
        for x in r:
            s += demands[x]
        return s

    def route_cost(r):
        if not r:
            return 0.0
        total = dist(0, r[0]) + dist(r[-1], 0)
        for i in range(len(r) - 1):
            total += dist(r[i], r[i + 1])
        return total

    def two_opt_route(r):
        if coords is None or len(r) < 4:
            return r[:]
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            m = len(best)
            for i in range(m - 2):
                for j in range(i + 2, m):
                    if i == 0 and j == m - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    # Local search: inter-route relocate and swap.
    def improve(routes):
        changed = True
        while changed:
            changed = False

            # Intra-route 2-opt
            for i in range(len(routes)):
                nr = two_opt_route(routes[i])
                if nr != routes[i]:
                    routes[i] = nr
                    changed = True

            # Inter-route relocate / swap
            best_move = None
            best_gain = 0.0

            for i in range(len(routes)):
                ri = routes[i]
                li = route_load(ri)
                ci = route_cost(ri)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj)
                    cj = route_cost(rj)

                    # relocate one customer from ri to rj
                    for a_idx, a in enumerate(ri):
                        da = demands[a]
                        if lj + da > capacity:
                            continue
                        ri_removed = ri[:a_idx] + ri[a_idx + 1:]
                        cost_ri_removed = route_cost(ri_removed)
                        for pos in range(len(rj) + 1):
                            rj_ins = rj[:pos] + [a] + rj[pos:]
                            cost_rj_ins = route_cost(rj_ins)
                            gain = (ci + cj) - (cost_ri_removed + cost_rj_ins)
                            if gain > best_gain + 1e-12:
                                best_gain = gain
                                best_move = ("relocate", i, j, a_idx, pos)

                    # swap one customer between routes
                    for a_idx, a in enumerate(ri):
                        da = demands[a]
                        for b_idx, b in enumerate(rj):
                            db = demands[b]
                            if li - da + db > capacity or lj - db + da > capacity:
                                continue
                            ri_sw = ri[:]
                            rj_sw = rj[:]
                            ri_sw[a_idx] = b
                            rj_sw[b_idx] = a
                            gain = (ci + cj) - (route_cost(ri_sw) + route_cost(rj_sw))
                            if gain > best_gain + 1e-12:
                                best_gain = gain
                                best_move = ("swap", i, j, a_idx, b_idx)

            if best_move is not None:
                typ = best_move[0]
                i = best_move[1]
                j = best_move[2]
                if typ == "relocate":
                    a_idx = best_move[3]
                    pos = best_move[4]
                    a = routes[i][a_idx]
                    routes[i].pop(a_idx)
                    routes[j].insert(pos, a)
                else:
                    a_idx = best_move[3]
                    b_idx = best_move[4]
                    routes[i][a_idx], routes[j][b_idx] = routes[j][b_idx], routes[i][a_idx]
                routes = [r for r in routes if r]
                changed = True

        return routes

    routes = improve(routes)

    # Repair: ensure all customers exactly once, remove duplicates, insert missing.
    seen = {}
    cleaned = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c < 1 or c > n:
                continue
            if seen.get(c, 0):
                continue
            if load + demands[c] > capacity:
                if nr:
                    cleaned.append(nr)
                nr = [c]
                load = demands[c]
            else:
                nr.append(c)
                load += demands[c]
            seen[c] = 1
        if nr:
            cleaned.append(nr)
    routes = cleaned

    missing = [c for c in customers if not seen.get(c, 0)]
    for c in missing:
        d = demands[c]
        best = None
        best_cost = None
        for r_idx, r in enumerate(routes):
            load = route_load(r)
            if load + d > capacity:
                continue
            for pos in range(len(r) + 1):
                cand = r[:pos] + [c] + r[pos:]
                delta = route_cost(cand) - route_cost(r)
                if best_cost is None or delta < best_cost - 1e-12:
                    best_cost = delta
                    best = (r_idx, pos)
        if best is None:
            routes.append([c])
        else:
            r_idx, pos = best
            routes[r_idx].insert(pos, c)

    routes = [r for r in routes if r]

    # Final light cleanup.
    routes = improve(routes)

    # Absolute safety: return only customer ids.
    return [r[:] for r in routes if r]
